#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: one-time npm release setup for airbnb-dlp, as described in
# docs/release.md under "One-time setup". Each stage checks whether its step
# is already done, so the wizard can be re-run after a failure.
#   scripts/release/setup-npm.sh
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=10
REPO=NickCrews/airbnb-dlp
PACKAGE=airbnb-dlp
FIRST_VERSION=1.0.0
PR_BRANCH=release/npm
ROOT=$(git -C "$(dirname "${BASH_SOURCE[0]}")" rev-parse --show-toplevel)
WORK="${TMPDIR:-/tmp}/airbnb-dlp-first-publish"
TARBALL="$WORK/$PACKAGE-$FIRST_VERSION.tgz"
TOKEN_DAYS=90

done_already() { printf '  %s✓ already done:%s %s\n' "$GREEN" "$RESET" "$1"; }
fail() { printf '  %s✗ %s%s\n' "$RED" "$1" "$RESET"; exit 1; }
run() { printf '  %s$ %s%s\n' "$DIM" "$*" "$RESET"; "$@"; }
published() { npm view "$PACKAGE@$FIRST_VERSION" version >/dev/null 2>&1; }
workflow_state() { gh api "repos/$REPO/actions/workflows/release.yml" --jq .state; }
remove_work() {
  git -C "$ROOT" worktree remove --force "$WORK/src" >/dev/null 2>&1 || true
  rm -rf "$WORK"
  git -C "$ROOT" worktree prune
}

banner "Publish airbnb-dlp $FIRST_VERSION and hand releases to CI"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Tools and the GitHub environment"
command -v gh >/dev/null 2>&1 || fail "gh is not installed."
gh auth status >/dev/null 2>&1 || fail "gh is not signed in: run gh auth login, then re-run this wizard."
command -v pnpm >/dev/null 2>&1 || fail "pnpm is not installed."
npm trust --help >/dev/null 2>&1 || fail "npm $(npm --version) has no 'npm trust': run npm install -g npm@latest."
say "gh, pnpm and npm $(npm --version) are ready."
if gh api "repos/$REPO/environments/npm" >/dev/null 2>&1; then
  done_already "GitHub environment npm exists"
else
  say "Creating the GitHub environment npm, deployable only from main."
  gh api -X PUT "repos/$REPO/environments/npm" \
    -F 'deployment_branch_policy[protected_branches]=false' -F 'deployment_branch_policy[custom_branch_policies]=true' >/dev/null
  gh api -X POST "repos/$REPO/environments/npm/deployment-branch-policies" -f name=main -f type=branch >/dev/null
  printf '  %s✓ created%s environment npm (main only)\n' "$GREEN" "$RESET"
fi
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Pause the Release workflow"
if published; then
  done_already "$PACKAGE@$FIRST_VERSION is on npm, so releases need no pause"
elif [[ "$(workflow_state)" != active ]]; then
  done_already "Release workflow is disabled"
else
  say "Merging the release tooling would start a release that cannot authenticate"
  say "to npm yet: the package does not exist, so it has no trusted publisher."
  say "Stage 10 turns the workflow back on."
  run gh workflow disable release.yml --repo "$REPO"
fi
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Merge the release pull request"
PR=$(gh pr list --repo "$REPO" --head "$PR_BRANCH" --state all --json number --jq '.[0].number // empty')
[[ -n "$PR" ]] || fail "No pull request from branch $PR_BRANCH."
opened=no
while :; do
  state=$(gh pr view "$PR" --repo "$REPO" --json state --jq .state)
  [[ "$state" == MERGED ]] && break
  [[ "$state" == CLOSED ]] && fail "Pull request #$PR was closed without merging."
  if [[ $opened == no ]]; then
    say "Pull request #$PR sets package.json to $FIRST_VERSION and adds the release workflow."
    open_url "https://github.com/$REPO/pull/$PR"
    step "Review it and merge it once its required checks pass."
    opened=yes
  fi
  pause "Press Enter once #$PR is merged."
done
SHA=$(gh pr view "$PR" --repo "$REPO" --json mergeCommit --jq .mergeCommit.oid)
done_already "#$PR merged as ${SHA:0:12}"
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Sign in to npm"
if NPM_USER=$(npm whoami 2>/dev/null); then
  done_already "signed in to npm as $NPM_USER"
else
  say "npm login opens npmjs.com in your browser. Sign in, or create the account"
  say "that will own $PACKAGE."
  run npm login
  NPM_USER=$(npm whoami)
fi
if npm profile get "two-factor auth" 2>/dev/null | grep -q 'auth-and-writes'; then
  done_already "two-factor authentication is on for sign-in and writes"
else
  say "The package owner's account should require two-factor authentication for"
  say "publishing. npm shows a QR code for your authenticator app."
  run npm profile enable-2fa auth-and-writes
fi
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Build $FIRST_VERSION and live-check the tarball"
if published; then
  done_already "$PACKAGE@$FIRST_VERSION is on npm"
else
  say "Builds the merge commit ${SHA:0:12} in $WORK, installs the tarball into an"
  say "empty project and runs the small live check against it: about 40 requests"
  say "to airbnb.com, the same check the Release workflow runs."
  remove_work
  mkdir -p "$WORK"
  git -C "$ROOT" fetch -q origin main
  run git -C "$ROOT" worktree add -q --detach "$WORK/src" "$SHA"
  (cd "$WORK/src" && pnpm install --frozen-lockfile --silent && pnpm test --silent && npm pack --pack-destination "$WORK")
  [[ -f "$TARBALL" ]] || fail "Expected $TARBALL. Is package.json's version $FIRST_VERSION at ${SHA:0:12}?"
  mkdir "$WORK/consumer"
  (cd "$WORK/consumer" && npm init -y >/dev/null && npm install --silent "$TARBALL")
  (cd "$WORK/src" && node scripts/live-check/run.ts --small --package "$WORK/consumer/node_modules/$PACKAGE" --out "$WORK/out") \
    || fail "The live check failed against the tarball; see $WORK/out/log.txt. Nothing was published."
  printf '  %s✓ passed%s the live check against %s\n' "$GREEN" "$RESET" "$TARBALL"
fi
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Publish $FIRST_VERSION to npm"
if published; then
  done_already "$PACKAGE@$FIRST_VERSION is on npm"
else
  [[ -f "$TARBALL" ]] || fail "No tarball at $TARBALL: re-run the wizard to rebuild it."
  warn "Publishing is permanent: npm never accepts $PACKAGE@$FIRST_VERSION again, even after unpublishing."
  note "Published from this machine, $FIRST_VERSION has no provenance; every later release has it."
  confirm "Publish $(basename "$TARBALL") to npm as $NPM_USER?" || fail "Stopped before publishing. Re-run to continue."
  run npm publish "$TARBALL" --access public
  for _ in 1 2 3 4 5 6; do published && break; sleep 5; done
  published || fail "npm publish finished but npm view does not show $FIRST_VERSION yet. Wait a minute and re-run."
  printf '  %s✓ published%s https://www.npmjs.com/package/%s\n' "$GREEN" "$RESET" "$PACKAGE"
fi
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Tag v$FIRST_VERSION and create its GitHub release"
if gh release view "v$FIRST_VERSION" --repo "$REPO" >/dev/null 2>&1; then
  done_already "GitHub release v$FIRST_VERSION exists"
else
  say "The tag tells the Release workflow that $FIRST_VERSION is out, so the next release is the next patch."
  notes="$(mktemp)"
  if [[ -f "$WORK/out/report.json" ]]; then
    mkdir -p "$WORK/reports/live-check-report-node"
    cp "$WORK/out/report.json" "$WORK/reports/live-check-report-node/"
    node "$ROOT/scripts/release/notes.ts" "$WORK/reports" > "$notes"
  fi
  printf '\nPublished from the maintainer'"'"'s machine, so this version has no npm provenance. Later versions are published by the Release workflow with provenance.\n' >> "$notes"
  run gh release create "v$FIRST_VERSION" --repo "$REPO" --target "$SHA" --title "v$FIRST_VERSION" --notes-file "$notes" --generate-notes
  rm -f "$notes"
fi
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Trust the Release workflow to publish"
if npm trust list "$PACKAGE" 2>/dev/null | grep -q 'release.yml'; then
  done_already "$PACKAGE trusts release.yml"
else
  say "npm will accept publishes from .github/workflows/release.yml in $REPO,"
  say "running in the GitHub environment npm, with no token."
  run npm trust github "$PACKAGE" --repo "$REPO" --file release.yml --env npm --allow-publish --yes
fi
run npm trust list "$PACKAGE"
pause

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Token for deprecating old versions"
say "CI deprecates earlier versions after a repair. Trusted publishing does not"
say "cover npm deprecate, so it needs a token limited to $PACKAGE, stored as"
say "the npm environment's secret NPM_TOKEN."
if gh secret list --repo "$REPO" --env npm 2>/dev/null | grep -q '^NPM_TOKEN' \
   && ! confirm "NPM_TOKEN is already set on the npm environment. Replace it?"; then
  done_already "NPM_TOKEN is set on the npm environment"
else
  note "npm prints the token once. Copy it (it starts with npm_) and paste it below."
  run npm token create --name "$PACKAGE-deprecate-$(date +%Y%m%d)" \
    --token-description "CI: npm deprecate after repairs ($REPO release.yml)" \
    --packages "$PACKAGE" --packages-and-scopes-permission read-write --bypass-2fa --expires "$TOKEN_DAYS"
  ask_secret NPM_DEPRECATE_TOKEN "Paste the token:"
  [[ "$NPM_DEPRECATE_TOKEN" == npm_* ]] || fail "That does not look like an npm token (npm_...). Re-run this wizard to try again."
  printf '%s' "$NPM_DEPRECATE_TOKEN" | gh secret set NPM_TOKEN --repo "$REPO" --env npm
  unset NPM_DEPRECATE_TOKEN
  WRITTEN_SECRET+=("NPM_TOKEN (environment npm)")
  printf '  %s✓ set%s secret NPM_TOKEN on environment npm\n' "$GREEN" "$RESET"
  expiry=$(date -v+"${TOKEN_DAYS}"d +%F 2>/dev/null || date -d "+${TOKEN_DAYS} days" +%F)
  warn "The token expires around $expiry. Rotate it before then (docs/release.md, Rotating NPM_TOKEN)."
fi
pause

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Resume the Release workflow"
if [[ "$(workflow_state)" == active ]]; then
  done_already "Release workflow is enabled"
else
  run gh workflow enable release.yml --repo "$REPO"
fi
remove_work
say "The next merge to main that changes the package is checked against"
say "airbnb.com and published as the next patch through trusted publishing."
pause

finish
note "npm:     https://www.npmjs.com/package/$PACKAGE"
note "release: https://github.com/$REPO/releases/tag/v$FIRST_VERSION"
note "runbook: docs/release.md"
printf '\n'
